ta[a0][c1] + PQ[c1]*delta[a0][c0])))

                            +(PQ[c0]*QC_x*(PQ[c1]*QD_y + PQ[g1]*QC_1) + PQ[c1]*QC_0*(PQ[g0]*QD_y + PQ[g1]*QC_x) + PQ[g0]*QC_1*(PQ[c0]*QD_y + PQ[g1]*QC_0))*(-PA_0*delta[b0][b1] - PB_0*delta[a0][b1] - PB_1*delta[a0][b0] + PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])

                        )

                        + F7_t[3] * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * a_l * (

                            +(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])*(PB_0*PQ[a0]*PQ[b1] + PQ[b0]*(PA_0*PQ[b1] + PB_1*PQ[a0]))

                            +(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0])*(PA_0*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PB_0*(PQ[a0]*delta[b1][g1] + PQ[b1]*delta[a0][g1]) + PB_1*(PQ[a0]*delta[b0][g1] + PQ[b0]*delta[a0][g1]))

                            +(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0])*(PB_0*PQ[b1]*PQ[g1] + PB_1*PQ[b0]*PQ[g1]) + (delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0])*(PA_0*PQ[b1]*PQ[g1] + PB_1*PQ[a0]*PQ[g1]) + (delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0])*(PA_0*PQ[b0]*PQ[g1] + PB_0*PQ[a0]*PQ[g1])

                            +PQ[g1]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0])*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0] - PQ[a0]*delta[b0][b1] - PQ[b0]*delta[a0][b1] - PQ[b1]*delta[a0][b0])

                        )

                        + F7_t[3] * 2.0 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_k * a_l * (

                            +PQ[a0]*PQ[b0]*PQ[b1]*(QC_0*(QC_1*delta[g0][g1] + QC_x*delta[c1][g1] + QD_y*delta[c1][g0]) + QC_1*(QC_x*delta[c0][g1] + QD_y*delta[c0][g0]) + QC_x*QD_y*delta[c0][c1])

                            +QC_0*QC_1*(PQ[a0]*(PQ[b0]*(QC_x*delta[b1][g1] + QD_y*delta[b1][g0]) + PQ[b1]*(QC_x*delta[b0][g1] + QD_y*delta[b0][g0])) + PQ[b0]*PQ[b1]*(QC_x*delta[a0][g1] + QD_y*delta[a0][g0])) + QC_x*QD_y*(PQ[a0]*(PQ[b0]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PQ[b1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + PQ[b0]*PQ[b1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))

                            +(QC_0*QD_y*(PQ[c1]*QC_x + PQ[g0]*QC_1) + QC_1*QC_x*(PQ[c0]*QD_y + PQ[g1]*QC_0))*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])

                        )

                        + F7_t[3] * (-1.0) * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_l * (

                            +PQ[a0]*PQ[b0]*PQ[b1]*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])

                            +(PQ[a0]*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PQ[b0]*PQ[b1]*delta[a0][g1])*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])

                            +QD_y*(PQ[a0]*(PQ[b0]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0]) + PQ[b1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0])) + PQ[b0]*PQ[b1]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0]))

                            +(PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0]) + QD_y*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]))*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])

