                        + F7_t[3] * 4.0 * S1 * S1 * S1 * inv_S4 * inv_S4 * inv_S4 * a_k * a_l * (

                            -PA_0*PB_0*PB_1*(PQ[c0]*PQ[c1]*(PQ[g0]*QD_y + PQ[g1]*QC_x) + PQ[g0]*PQ[g1]*(PQ[c0]*QC_1 + PQ[c1]*QC_0))

