                        + F7_t[0] * (

                            +PA_0*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1])

                        )

                        + F7_t[0] * 0.5 * inv_S1 * inv_S1 * inv_S2 * a_j * a_k * (

                            +(QC_0*delta[c1][g1] + QC_1*delta[c0][g1] + QC_y*delta[c0][c1])*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])

                        )

                        + F7_t[0] * inv_S1 * inv_S1 * a_j * a_k * (

                            +QC_0*QC_1*QC_y*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])

                        )

                        + F7_t[0] * 0.5 * inv_S1 * (

                            +(QC_0*delta[c1][g1] + QC_1*delta[c0][g1])*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0])

