                            -(PQ[c1]*QC_0*QC_y + QC_1*(PQ[c0]*QC_y + PQ[g1]*QC_0))*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])

                        )

                        + F7_t[1] * 0.5 * inv_S1 * inv_S4 * a_j * (

                            -delta[c0][g1]*(PA_0*(delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1]) + PB_0*(delta[a0][b1]*delta[c1][g0] + delta[a0][c1]*delta[b1][g0] + delta[a0][g0]*delta[b1][c1]) + PB_1*(delta[a0][b0]*delta[c1][g0] + delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1]) + PB_x*(delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])) - delta[c1][g1]*(PA_0*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + PB_0*(delta[a0][b1]*delta[c0][g0] + delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0]) + PB_1*(delta[a0][b0]*delta[c0][g0] + delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0]) + PB_x*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))

                            +(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1])*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])

                        )

                        + F7_t[1] * inv_S2 * inv_S4 * a_j * a_k * (

                            +PA_0*PB_0*(PB_1*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + PB_x*(delta[b1][c0]*delta[c1][g1] + delta[b1][c1]*delta[c0][g1] + delta[b1][g1]*delta[c0][c1])) + PB_1*PB_x*(PA_0*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1] + delta[b0][g1]*delta[c0][c1]) + PB_0*(delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1]))

                            -(PA_0*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0] + PB_x*delta[b0][b1]) + PB_0*(PB_1*delta[a0][g0] + PB_x*delta[a0][b1]) + PB_1*PB_x*delta[a0][b0])*(delta[c0][c1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0))

