                            +QC_0*QC_1*QC_y*(PA_0*(-PB_0*delta[b1][g0] - PB_1*delta[b0][g0] - PB_x*delta[b0][b1] + PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_0*(PQ[a0]*delta[b1][g0] + delta[a0][b1]*(-PB_x + PQ[g0]) + delta[a0][g0]*(-PB_1 + PQ[b1])) + PB_1*(PQ[a0]*delta[b0][g0] + PQ[b0]*delta[a0][g0] + delta[a0][b0]*(-PB_x + PQ[g0])) + PB_x*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0]))

                        )

                        + F7_t[1] * S2 * inv_S1 * inv_S4 * a_j * (

                            +(QC_0*delta[c1][g1] + QC_1*delta[c0][g1])*(PA_0*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0] + PB_x*delta[b0][b1]) - PA_0*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_0*(PB_1*delta[a0][g0] + PB_x*delta[a0][b1]) - PB_0*(PQ[a0]*delta[b1][g0] + PQ[b1]*delta[a0][g0] + PQ[g0]*delta[a0][b1]) + PB_1*PB_x*delta[a0][b0] - PB_1*(PQ[a0]*delta[b0][g0] + PQ[b0]*delta[a0][g0] + PQ[g0]*delta[a0][b0]) - PB_x*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0]))

