                            +PQ[c0]*PQ[c1]*PQ[d0]*(PQ[a0]*PQ[g1]*(PB_0*PQ[b1]*PQ[g0] + PQ[b0]*(PA_x*PQ[b1] + PB_1*PQ[g0])) + PQ[b0]*PQ[b1]*PQ[g0]*(PA_0*PQ[g1] + PA_y*PQ[a0]))

