                            +(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0])*(PB_1*PQ[d0]*PQ[g0]*QC_y + PB_1*PQ[d0]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QD_0) + (delta[a0][c0]*delta[b0][d0] + delta[a0][d0]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[g0]*QC_y + PB_1*PQ[c1]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[d0]*QC_y + PB_1*PQ[c1]*PQ[g1]*QD_0 + PB_1*PQ[d0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b0][g1] + delta[a0][g1]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[d0]*QC_x + PB_1*PQ[c1]*PQ[g0]*QD_0 + PB_1*PQ[d0]*PQ[g0]*QC_1) + (delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0])*(PB_0*PQ[d0]*PQ[g0]*QC_y + PB_0*PQ[d0]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QD_0) + (delta[a0][c0]*delta[b1][d0] + delta[a0][d0]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[g0]*QC_y + PB_0*PQ[c1]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[d0]*QC_y + PB_0*PQ[c1]*PQ[g1]*QD_0 + PB_0*PQ[d0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b1][g1] + delta[a0][g1]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[d0]*QC_x + PB_0*PQ[c1]*PQ[g0]*QD_0 + PB_0*PQ[d0]*PQ[g0]*QC_1) + (delta[a0][c1]*delta[b0][d0] + delta[a0][d0]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[g0]*QC_y + PB_1*PQ[c0]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[d0]*QC_y + PB_1*PQ[c0]*PQ[g1]*QD_0 + PB_1*PQ[d0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b0][g1] + delta[a0][g1]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[d0]*QC_x + PB_1*PQ[c0]*PQ[g0]*QD_0 + PB_1*PQ[d0]*PQ[g0]*QC_0) + (delta[a0][c1]*delta[b1][d0] + delta[a0][d0]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[g0]*QC_y + PB_0*PQ[c0]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b1][g0] + delta[a0][g0]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[d0]*QC_y + PB_0*PQ[c0]*PQ[g1]*QD_0 + PB_0*PQ[d0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b1][g1] + delta[a0][g1]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[d0]*QC_x + PB_0*PQ[c0]*PQ[g0]*QD_0 + PB_0*PQ[d0]*PQ[g0]*QC_0) + (delta[a0][