                            +PQ[a0]*PQ[b0]*PQ[b1]*PQ[d0]*(PQ[c0]*(PQ[c1]*delta[g0][g1] + PQ[g0]*delta[c1][g1] + PQ[g1]*delta[c1][g0]) + PQ[c1]*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0]))

