delta[a0][d0]*(delta[c0][c1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + delta[a0][g1]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0)))) - PB_1*(delta[a0][b0]*(delta[c0][g0]*(delta[c1][d0]*(PQ[g1] + QC_y) + delta[c1][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c1] + QC_1)) + delta[c1][g0]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[d0][g0]*(delta[c0][c1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + delta[g0][g1]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))) + delta[a0][g0]*(delta[b0][c0]*(delta[c1][d0]*(PQ[g1] + QC_y) + delta[c1][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c1] + QC_1)) + delta[b0][c1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[b0][d0]*(delta[c0][c1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + delta[b0][g1]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))) + delta[b0][g0]*(delta[a0][c0]*(delta[c1][d0]*(PQ[g1] + QC_y) + delta[c1][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c1] + QC_1)) + delta[a0][c1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[a0][d0]*(delta[c0][c1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + delta[a0][g1]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))))

                            +(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(PQ[c0]*(delta[c1][d0]*(PQ[g1] + QC_y) + delta[c1][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c1] + QC_1)) + PQ[c1]*(QC_0*delta[d0][g1] + delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1] + delta[c0][c1]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0] + QD_0*delta[c0][c1]))

                        )

                        + F8_t[2] * 0.25 * inv_S2 * inv_S4 * inv_S4 * a_k * (

                            -2*delta[a0][g0]*delta[b0][b1]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0])

