1 - PQ[b0]*PQ[b1]*PQ[c1]*QD_0 - PQ[b0]*PQ[b1]*PQ[d0]*QC_1) + (delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0])*(PB_0*PQ[b1]*PQ[c0]*QD_0 + PB_0*PQ[b1]*PQ[d0]*QC_0 + PB_1*PQ[b0]*PQ[c0]*QD_0 + PB_1*PQ[b0]*PQ[d0]*QC_0 - PQ[b0]*PQ[b1]*PQ[c0]*QD_0 - PQ[b0]*PQ[b1]*PQ[d0]*QC_0) + (delta[a0][d0]*delta[g0][g1] + delta[a0][g0]*delta[d0][g1] + delta[a0][g1]*delta[d0][g0])*(PB_0*PQ[b1]*PQ[c0]*QC_1 + PB_0*PQ[b1]*PQ[c1]*QC_0 + PB_1*PQ[b0]*PQ[c0]*QC_1 + PB_1*PQ[b0]*PQ[c1]*QC_0 - PQ[b0]*PQ[b1]*PQ[c0]*QC_1 - PQ[b0]*PQ[b1]*PQ[c1]*QC_0) + (delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])*(PA_0*PQ[c1]*PQ[g1]*QD_0 + PA_0*PQ[d0]*PQ[g1]*QC_1 + PB_y*PQ[a0]*PQ[c1]*QD_0 + PB_y*PQ[a0]*PQ[d0]*QC_1 - PQ[a0]*PQ[c1]*PQ[g1]*QD_0 - PQ[a0]*PQ[d0]*PQ[g1]*QC_1) + (delta[b0][b1]*delta[c0][g1] + delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])*(PA_0*PQ[c1]*PQ[g0]*QD_0 + PA_0*PQ[d0]*PQ[g0]*QC_1 + PA_x*PQ[a0]*PQ[c1]*QD_0 + PA_x*PQ[a0]*PQ[d0]*QC_1 - PQ[a0]*PQ[c1]*PQ[g0]*QD_0 - PQ[a0]*PQ[d0]*PQ[g0]*QC_1) + (delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1])*(PA_0*PQ[c0]*PQ[g1]*QD_0 + PA_0*PQ[d0]*PQ[g1]*QC_0 + PB_y*PQ[a0]*PQ[c0]*QD_0 + PB_y*PQ[a0]*PQ[d0]*QC_0 - PQ[a0]*PQ[c0]*PQ[g1]*QD_0 - PQ[a0]*PQ[d0]*PQ[g1]*QC_0) + (delta[b0][b1]*delta[c1][g1] + delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1])*(PA_0*PQ[c0]*PQ[g0]*QD_0 + PA_0*PQ[d0]*PQ[g0]*QC_0 + PA_x*PQ[a0]*PQ[c0]*QD_0 + PA_x*PQ[a0]*PQ[d0]*QC_0 - PQ[a0]*PQ[c0]*PQ[g0]*QD_0 - PQ[a0]*PQ[d0]*PQ[g0]*QC_0) + (delta[b0][b1]*delta[d0][g0] + delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0])*(PA_0*PQ[c0]*PQ[g1]*QC_1 + PA_0*PQ[c1]*PQ[g1]*QC_0 + PB_y*PQ[a0]*PQ[c0]*QC_1 + PB_y*PQ[a0]*PQ[c1]*QC_0 - PQ[a0]*PQ[c0]*PQ[g1]*QC_1 - PQ[a0]*PQ[c1]*PQ[g1]*QC_0) + (delta[b0][b1]*delta[d0][g1] + delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])*(PA_0*PQ[c0]*PQ[g0]*QC_1 + PA_0*PQ[c1]*PQ[g0]*QC_0 + PA_x*PQ[a0]*PQ[c0]*QC_1 + PA_x*PQ[a0]*PQ[c1]*QC_0 - PQ[a0]*PQ[c0]*PQ[g0]*QC_1 - PQ[a0]*PQ[c1]*PQ[g0]*QC_0) + (delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0])*(PA_0*PQ[b1]*PQ[c1]*QD_0 + PA_0*PQ[b1]*PQ[d0]*QC_1 + PB_1*PQ[a0]*PQ[c1]*QD_0 + PB_1*PQ[a0]*PQ[d0]*QC_1 - PQ[a0]*PQ[b1]*PQ[c1]*QD_0 - PQ[a0]*PQ[b1]*PQ[d0]*QC_1) + (delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0])*(PA_0*PQ[b1]*PQ[c0]*QD_0 + PA_0*PQ[b1]*PQ[d0]*QC_0 + PB_1*PQ[a0]*PQ[c0]*QD_0 + PB_1*PQ[a0]*PQ[d0]*QC_0 - PQ[a0]*PQ[b1]*PQ[c0]*QD_0 - PQ[a0]*PQ[b1]*PQ[d0]*QC_0) + (delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0])*(PA_0*PQ[b1]*PQ[c0]*QC_1 + PA_0*PQ[b1]*PQ[c1]*QC_0 + PB_1*PQ[a0]*PQ[c0]*QC_1 + PB_1*PQ[a0]*PQ[c1]*QC_0 - PQ[a0]*PQ[b1]*PQ[c0]*QC_1 - PQ[a0]*PQ[b1]*PQ[c1]*QC_0) + (delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0])*(PA_0*PQ[b0]*PQ[c1]*QD_0 + PA_0*PQ[b0]*PQ[d0]*QC_1 + PB_0*PQ[a0]*PQ[c1]*QD_0 + PB_0*PQ[a0]*PQ[d0]*QC_1 - PQ[a0]*PQ[b0]*PQ[c1]*QD_0 - PQ[a0]*PQ[b0]*PQ[d0]*QC_1) + (delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0])*(PA_0*PQ[b0]*PQ[c0]*QD_0 + PA_0*PQ[b0]*PQ[d0]*QC_0 + PB_0*PQ[a0]*PQ[c0]*QD_0 + PB_0*PQ[a0]*PQ[d0]*QC_0 - PQ[a0]*PQ[b0]*PQ[c0]*QD_0 - PQ[a0]*PQ[b0]*PQ[d0]*QC_0) + (delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0])*(PA_0*PQ[b0]*PQ[c0]*QC_1 + PA_0*PQ[b0]*PQ[c1]*QC_0 + PB_0*PQ[a0]*PQ[c0]*QC_1 + PB_0*PQ[a0]*PQ[c1]*QC_0 - PQ[a0]*PQ[b0]*PQ[c0]*QC_1 - PQ[a0]*PQ[b0]*PQ[c1]*QC_0)

                            +(PQ[c0]*(PQ[c1]*QD_0 + PQ[d0]*QC_1) + PQ[c1]*PQ[d0]*QC_0)*(PA_0*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + PB_0*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PB_1*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + PB_y*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) - 2*PQ[a0]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) - 2*PQ[b0]*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) - 2*PQ[b1]*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) - 2*PQ[g0]*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) - 2*PQ[g1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]))

                            +(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1])*(PA_x*PQ[b0]*PQ[b1]*PQ[g1] + PB_0*PQ[b1]*PQ[g0]*PQ[g1] + PB_1*PQ[b0]*PQ[g0]*PQ[g1] + PB_y*PQ[b0]*PQ[b1]*PQ[g0]) + (delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1])*(PA_0*PQ[b1]*PQ[g0]*PQ[g1] + PA_x*PQ[a0]*PQ[b1]*PQ[g1] + PB_1*PQ[a0]*PQ[g0]*PQ[g1] + PB_y*PQ[a0]*PQ[b1]*PQ[g0]) + (delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1])*(PA_0*PQ[b0]*PQ[g0]*PQ[g1] + PA_x*PQ[a0]*PQ[b0]*PQ[g1] + PB_0*PQ[a0]*PQ[g0]*PQ[g1] + PB_y*PQ[a0]*PQ[b0]*PQ[g0]) + (delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])*(PA_0*PQ[b0]*PQ[b1]*PQ[g1] + PB_0*PQ[a0]*PQ[b1]*PQ[g1] + PB_1*PQ[a0]*PQ[b0]*PQ[g1] + PB_y*PQ[a0]*PQ[b0]*PQ[b1]) + (delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0])*(PA_0*PQ[b0]*PQ[b1]*PQ[g0] + PA_x*PQ[a0]*PQ[b0]*PQ[b1] + PB_0*PQ[a0]*PQ[b1]*PQ[g0] + PB_1*PQ[a0]*PQ[b0]*PQ[g0])

