Q[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0)) + delta[b1][g0]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0)))) + PB_1*(QC_0*(PQ[c1]*(delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0]) + PQ[d0]*(delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0]) + PQ[g0]*(delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1] + delta[b0][g1]*delta[c1][d0]) + PQ[g1]*(delta[b0][c1]*delta[d0][g0] + delta[b0][d0]*delta[c1][g0] + delta[b0][g0]*delta[c1][d0])) + QC_1*(PQ[d0]*(delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0]) + PQ[g0]*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0]) + PQ[g1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + (PQ[c0] + QC_0)*(delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0])) + QC_x*(PQ[g1]*(delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1]) + (PQ[c0] + QC_0)*(delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1] + delta[b0][g1]*delta[c1][d0]) + (PQ[c1] + QC_1)*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0]) + (PQ[d0] + QD_0)*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1] + delta[b0][g1]*delta[c0][c1])) + QD_0*(PQ[g0]*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1] + delta[b0][g1]*delta[c0][c1]) + PQ[g1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1]) + (PQ[c0] + QC_0)*(delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0]) + (PQ[c1] + QC_1)*(delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0])) + QD_y*(delta[b0][c0]*(delta[c1][d0]*(PQ[g0] + QC_x) + delta[c1][g0]*(PQ[d0] + QD_0) + delta[d0][g0]*(PQ[c1] + QC_1)) + delta[b0][c1]*(delta[c0][d0]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[d0] + QD_0) + delta[d0][g0]*(PQ[c0] + QC_0)) + delta[b0][d0]*(delta[c0][c1]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0)) + delta[b0][g0]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))))) - PB_0*PB_1*(QC_0*(PQ[c1]*(delta[a0][d0]*delta[g0][g1] + delta[a0][g0]*delta[d0][g1] + delta[a0][g1]*delta[d0][g0]) + PQ[d0]*(delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0]) + PQ[g0]*(delta[a0][c1]*delta[d0][g1] + delta[a0][d0]*delta[c1][g1] + delta[a0][g1]*delta[c1][d0]) + PQ[g1]*(delta[a0][c1]*delta[d0][g0] + delta[a0][d0]*delta[c1][g0] + delta[a0][g0]*delta[c1][d0])) + QC_1*(PQ[d0]*(delta[a0][c0]*delta[g0][g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0]) + PQ[g0]*(delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0]) + PQ[g1]*(delta[a0][c0]*delta[d0][g0] + delta[a0][d0]*delta[c0][g0] + delta[a0][g0]*delta[c0][d0]) + (PQ[c0] + QC_0)*(delta[a0][d0]*delta[g0][g1] + delta[a0][g0]*delta[d0][g1] + delta[a0][g1]*delta[d0][g0])) + QC_x*(PQ[g1]*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1]) + (PQ[c0] + QC_0)*(delta[a0][c1]*delta[d0][g1] + delta[a0][d0]*delta[c1][g1] + delta[a0][g1]*delta[c1][d0]) + (PQ[c1] + QC_1)*(delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0]) + (PQ[d0] + QD_0)*(delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1])) + QD_0*(PQ[g0]*(delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1]) + PQ[g1]*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1]) + (PQ[c0] + QC_0)*(delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0]) + (PQ[c1] + QC_1)*(delta[a0][c0]*delta[g0][g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0])) + QD_y*(delta[a0][c0]*(delta[c1][d0]*(PQ[g0] + QC_x) + delta[c1][g0]*(PQ[d0] + QD_0) + delta[d0][g0]*(PQ[c1] + QC_1)) + delta[a0][c1]*(delta[c0][d0]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[d0] + QD_0) + delta[d0][g0]*(PQ[c0] + QC_0)) + delta[a0][d0]*(delta[c0][c1]*(PQ[g0] + QC_x) + delta[c0][g0]*(PQ[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0)) + delta[a0][g0]*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0))))

                            +(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0])*(PQ[d0]*QC_1*(delta[c0][g0]*(PQ[g1] + QD_y) + delta[c0][g1]*(PQ[g0] + QC_x) + delta[g0][g1]*(PQ[c0] + QC_0)) + PQ[g0]*((PQ[c0] + QC_0)*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1]) + (PQ[g1] + QD_y)*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0] + QD_0*delta[c0][c1])) + PQ[g1]*(PQ[c0] + QC_0)*(QC_1*delta[d0][g0] + QC_x*delta[c1][d0] + QD_0*delta[c1][g0]) + QC_0*(PQ[c1]*(delta[d0][g0]*(PQ[g1] + QD_y) + delta[d0][g1]*(PQ[g0] + QC_x) + delta[g0][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(delta[c1][g0]*(PQ[g1] + QD_y) + delta[c1][g1]*(PQ[g0] + QC_x))) + QD_y*(PQ[g0] + QC_x)*(PQ[c0]*delta[c1][d0] + PQ[c1]*delta[c0][d0] + PQ[d0]*delta[c0][c1]) + (PQ[c1] + QC_1)*(PQ[c0]*(QC_x*delta[d0][g1] + QD_0*delta[g0][g1] + QD_y*delta[d0][g0]) + PQ[g1]*QC_x*delta[c0][d0] + QD_0*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0])) + (PQ[d0] + QD_0)*(QC_x*(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1] + PQ[g1]*delta[c0][c1]) + QD_y*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0])))

                        )

                        + F8_t[2] * 0.5 * S1 * inv_S2 * inv_S4 * inv_S4 * a_k * (

                            +delta[d0][g1]*(PA_0*(PB_0*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + PB_1*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1])) + PB_0*PB_1*(delta[a0][c0]*delta[c1][g0] + delta[a0][c1]*delta[c0][g0] + delta[a0][g0]*delta[c0][c1]))

                            -delta[d0][g1]*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0])*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0] + PQ[g0]*delta[c0][c1])

                        )

                        + F8_t[2] * 0.5 * S1 * inv_S2 * inv_S4 * inv_S4 * a_l * (

                            +PA_0*(PB_0*(delta[c0][g0]*(delta[b1][c1]*delta[d0][g1] + delta[b1][d0]*delta[c1][g1] + delta[b1][g1]*delta[c1][d0]) + delta[c1][g0]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0])) + PB_1*(delta[c0][g0]*(delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1] + delta[b0][g1]*delta[c1][d0]) + delta[c1][g0]*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0]))) + PB_0*PB_1*(delta[c0][g0]*(delta[a0][c1]*delta[d0][g1] + delta[a0][d0]*delta[c1][g1] + delta[a0][g1]*delta[c1][d0]) + delta[c1][g0]*(delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0]))

                            -delta[d0][g1]*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0])*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0])

                            -(PQ[d0]*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + PQ[g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0])

                        )

                        + F8_t[2] * (-1.0) * S2 * inv_S1 * inv_S4 * inv_S4 * a_k * a_l * (

                            +(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])*(QC_0*(QC_1*(QC_x*delta[d0][g1] + QD_0*delta[g0][g1] + QD_y*delta[d0][g0]) + QD_y*(QC_x*delta[c1][d0] + QD_0*delta[c1][g0])) + QC_1*QD_y*(QC_x*delta[c0][d0] + QD_0*delta[c0][g0]) + QC_x*QD_0*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1] + QD_y*delta[c0][c1]))

                            +QC_0*QD_0*QD_y*(QC_1*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) + QC_x*(delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])) + QC_1*QC_x*(QC_0*(QD_0*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + QD_y*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1])) + QD_0*QD_y*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))

                        )

                        + F8_t[2] * 0.5 * S2 * inv_S1 * inv_S4 * inv_S4 * a_l * (

                            +(QD_0*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + QD_y*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])

                            +(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])*(QD_0*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + QD_y*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1]))

                            +QD_0*QD_y*(delta[c0][g0]*(delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1]) + delta[c1][g0]*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))

                            +delta[d0][g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])*(PQ[a0]*delta[b0][b1] + PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0])

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + l_prim],
                hess_kl_xy * ik_factor_D * 2.0 * frac_exact_exchange);
        }
    }

    __syncthreads();
}

__global__ void __launch_bounds__(TILE_SIZE_K)
computeExchangeHessianPDDP_KL_3(double*         hess_xy,
                                double*         hess_yx,
                                const uint32_t  hess_cart_ind_0,
                                const uint32_t  hess_cart_ind_1,
                                const double    frac_exact_exchange,
                                const uint32_t* pair_inds_i_for_K_pd,
                                const uint32_t* pair_inds_k_for_K_pd,
                                const double*   D_ik_for_K_pd,
                                const uint32_t  pair_inds_count_for_K_pd,
                                const double*   p_prim_info,
                                const uint32_t* p_prim_aoinds,
                                const uint32_t  p_prim_count,
                                const double*   d_prim_info,
                                const uint32_t* d_prim_aoinds,
                                const uint32_t  d_prim_count,
                                const double    dp_max_D,
                                const double*   mat_D_full_AO,
                                const uint32_t  naos,
                                const double*   Q_K_pd,
                                const double*   Q_K_dp,
                                const uint32_t* D_inds_K_pd,
                                const uint32_t* D_inds_K_dp,
                                const uint32_t* pair_displs_K_pd,
                                const uint32_t* pair_displs_K_dp,
                                const uint32_t* pair_counts_K_pd,
                                const uint32_t* pair_counts_K_dp,
                                const double*   pair_data_K_pd,
                                const double*   pair_data_K_dp,
                                const uint32_t* prim_cart_ao_to_atom_inds,
                                const uint32_t  natoms,
                                const uint32_t  s_prim_count,
                                const double*   boys_func_table,
                                const double*   boys_func_ft,
                                const double    omega,
                                const double    eri_threshold)
{
    // each thread block scans over [i?|k?] and sum up to a primitive K matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ uint32_t i, k, count_i, count_k, displ_i, displ_k;
    __shared__ double   a_i, r_i[3], a_k, r_k[3], ik_factor_D;
    __shared__ uint32_t a0, c0, c1;
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    const uint32_t ik = blockIdx.x;

    // we make sure that ik < pair_inds_count_for_K_pd when calling the kernel

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
