                            +(PQ[c0]*(PQ[c1]*(delta[d0][g0]*(PQ[g1] + QD_y) + delta[d0][g1]*(PQ[g0] + QC_x) + delta[g0][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_1*delta[g0][g1] + delta[c1][g0]*(PQ[g1] + QD_y) + delta[c1][g1]*(PQ[g0] + QC_x)) + PQ[g0]*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1] + delta[c1][d0]*(PQ[g1] + QD_y)) + PQ[g1]*(QC_1*delta[d0][g0] + QC_x*delta[c1][d0] + QD_0*delta[c1][g0])) + PQ[c1]*(PQ[d0]*(QC_0*delta[g0][g1] + delta[c0][g0]*(PQ[g1] + QD_y) + delta[c0][g1]*(PQ[g0] + QC_x)) + PQ[g0]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QD_y)) + PQ[g1]*(QC_0*delta[d0][g0] + QC_x*delta[c0][d0] + QD_0*delta[c0][g0])) + PQ[d0]*(PQ[g0]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1] + delta[c0][c1]*(PQ[g1] + QD_y)) + PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0] + QC_x*delta[c0][c1])) + PQ[g0]*PQ[g1]*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0] + QD_0*delta[c0][c1]))*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0] - PQ[a0]*delta[b0][b1] - PQ[b0]*delta[a0][b1] - PQ[b1]*delta[a0][b0])

                            +(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0])*(PB_1*PQ[d0]*PQ[g0]*QD_y + PB_1*PQ[d0]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QD_0) + (delta[a0][c0]*delta[b0][d0] + delta[a0][d0]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[g0]*QD_y + PB_1*PQ[c1]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[d0]*QD_y + PB_1*PQ[c1]*PQ[g1]*QD_0 + PB_1*PQ[d0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b0][g1] + delta[a0][g1]*delta[b0][c0])*(PB_1*PQ[c1]*PQ[d0]*QC_x + PB_1*PQ[c1]*PQ[g0]*QD_0 + PB_1*PQ[d0]*PQ[g0]*QC_1) + (delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0])*(PB_0*PQ[d0]*PQ[g0]*QD_y + PB_0*PQ[d0]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QD_0) + (delta[a0][c0]*delta[b1][d0] + delta[a0][d0]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[g0]*QD_y + PB_0*PQ[c1]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[d0]*QD_y + PB_0*PQ[c1]*PQ[g1]*QD_0 + PB_0*PQ[d0]*PQ[g1]*QC_1) + (delta[a0][c0]*delta[b1][g1] + delta[a0][g1]*delta[b1][c0])*(PB_0*PQ[c1]*PQ[d0]*QC_x + PB_0*PQ[c1]*PQ[g0]*QD_0 + PB_0*PQ[d0]*PQ[g0]*QC_1) + (delta[a0][c1]*delta[b0][d0] + delta[a0][d0]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[g0]*QD_y + PB_1*PQ[c0]*PQ[g1]*QC_x + PB_1*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[d0]*QD_y + PB_1*PQ[c0]*PQ[g1]*QD_0 + PB_1*PQ[d0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b0][g1] + delta[a0][g1]*delta[b0][c1])*(PB_1*PQ[c0]*PQ[d0]*QC_x + PB_1*PQ[c0]*PQ[g0]*QD_0 + PB_1*PQ[d0]*PQ[g0]*QC_0) + (delta[a0][c1]*delta[b1][d0] + delta[a0][d0]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[g0]*QD_y + PB_0*PQ[c0]*PQ[g1]*QC_x + PB_0*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b1][g0] + delta[a0][g0]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[d0]*QD_y + PB_0*PQ[c0]*PQ[g1]*QD_0 + PB_0*PQ[d0]*PQ[g1]*QC_0) + (delta[a0][c1]*delta[b1][g1] + delta[a0][g1]*delta[b1][c1])*(PB_0*PQ[c0]*PQ[d0]*QC_x + PB_0*PQ[c0]*PQ[g0]*QD_0 + PB_0*PQ[d0]*PQ[g0]*QC_0) + (delta[a0][