            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F8_t[3] * 2.0 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                            +delta[d0][g1]*(PQ[c0]*QC_1 + PQ[c1]*QC_0)*(PA_0*PQ[b0]*(PA_x*PQ[b1] + PB_1*PQ[g0]) + PB_0*PQ[b1]*(PA_0*PQ[g0] + PA_x*PQ[a0]) + PB_1*PQ[a0]*(PA_x*PQ[b0] + PB_0*PQ[g0]))

