                        + F8_t[3] * 2.0 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_l * (

                            +PQ[b0]*PQ[b1]*delta[a0][g0]*(QC_0*QD_y*(PQ[c1]*QD_0 + PQ[d0]*QC_1) + QC_1*QD_0*(PQ[c0]*QD_y + PQ[g1]*QC_0))

                        )

                        + F8_t[3] * (-1.0) * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * (

                            +PQ[b0]*PQ[b1]*delta[a0][g0]*delta[d0][g1]*(PQ[c0]*QC_1 + PQ[c1]*QC_0)

