                        + F8_t[3] * 4.0 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_i * a_l * (

                            +QC_0*QC_1*QD_0*QD_y*(PQ[a0]*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PQ[b0]*PQ[b1]*(PA_0*PQ[g0] + PA_x*PQ[a0]))

