                        + F8_t[3] * 0.25 * S2 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                            +delta[d0][g1]*(delta[a0][b0]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + delta[a0][b1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0] + delta[b0][g0]*delta[c0][c1]) + delta[a0][c0]*(delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1]) + delta[a0][c1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + delta[a0][g0]*(delta[b0][b1]*delta[c0][c1] + delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0]))

