                            +delta[c0][c1]*delta[d0][g1]*(PQ[a0]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PQ[b0]*(PQ[b1]*delta[a0][g0] + PQ[g0]*delta[a0][b1]) + PQ[b1]*PQ[g0]*delta[a0][b0])

