                            +(-PA_0*PQ[b0] - PB_0*PQ[a0])*(delta[b1][c0]*delta[c1][d0]*delta[g0][g1] + delta[b1][c0]*delta[c1][g0]*delta[d0][g1] + delta[b1][c0]*delta[c1][g1]*delta[d0][g0] + delta[b1][c1]*delta[c0][d0]*delta[g0][g1] + delta[b1][c1]*delta[c0][g0]*delta[d0][g1] + delta[b1][c1]*delta[c0][g1]*delta[d0][g0] + delta[b1][d0]*delta[c0][c1]*delta[g0][g1] + delta[b1][d0]*delta[c0][g0]*delta[c1][g1] + delta[b1][d0]*delta[c0][g1]*delta[c1][g0] + delta[b1][g1]*delta[c0][c1]*delta[d0][g0] + delta[b1][g1]*delta[c0][d0]*delta[c1][g0] + delta[b1][g1]*delta[c0][g0]*delta[c1][d0]) + (-PA_0*PQ[b1] - PB_1*PQ[a0])*(delta[b0][c0]*delta[c1][d0]*delta[g0][g1] + delta[b0][c0]*delta[c1][g0]*delta[d0][g1] + delta[b0][c0]*delta[c1][g1]*delta[d0][g0] + delta[b0][c1]*delta[c0][d0]*delta[g0][g1] + delta[b0][c1]*delta[c0][g0]*delta[d0][g1] + delta[b0][c1]*delta[c0][g1]*delta[d0][g0] + delta[b0][d0]*delta[c0][c1]*delta[g0][g1] + delta[b0][d0]*delta[c0][g0]*delta[c1][g1] + delta[b0][d0]*delta[c0][g1]*delta[c1][g0] + delta[b0][g1]*delta[c0][c1]*delta[d0][g0] + delta[b0][g1]*delta[c0][d0]*delta[c1][g0] + delta[b0][g1]*delta[c0][g0]*delta[c1][d0]) + (-PA_0*PQ[g0] - PA_x*PQ[a0])*(delta[b0][c0]*delta[b1][c1]*delta[d0][g1] + delta[b0][c0]*delta[b1][d0]*delta[c1][g1] + delta[b0][c0]*delta[b1][g1]*delta[c1][d0] + delta[b0][c1]*delta[b1][c0]*delta[d0][g1] + delta[b0][c1]*delta[b1][d0]*delta[c0][g1] + delta[b0][c1]*delta[b1][g1]*delta[c0][d0] + delta[b0][d0]*delta[b1][c0]*delta[c1][g1] + delta[b0][d0]*delta[b1][c1]*delta[c0][g1] + delta[b0][d0]*delta[b1][g1]*delta[c0][c1] + delta[b0][g1]*delta[b1][c0]*delta[c1][d0] + delta[b0][g1]*delta[b1][c1]*delta[c0][d0] + delta[b0][g1]*delta[b1][d0]*delta[c0][c1]) + (-PA_x*PQ[b0] - PB_0*PQ[g0])*(delta[a0][c0]*delta[b1][c1]*delta[d0][g1] + delta[a0][c0]*delta[b1][d0]*delta[c1][g1] + delta[a0][c0]*delta[b1][g1]*delta[c1][d0] + delta[a0][c1]*delta[b1][c0]*delta[d0][g1] + delta[a0][c1]*delta[b1][d0]*delta[c0][g1] + delta[a0][c1]*delta[b1][g1]*delta[c0][d0] + 