                        )

                        + F8_t[4] * 4.0 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_l * (

                            +PQ[a0]*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*QD_0*QD_y

                        )

                        + F8_t[4] * (-2.0) * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                            +PQ[a0]*PQ[b0]*PQ[b1]*PQ[g0]*QC_0*QC_1*delta[d0][g1]

                        )

                        + F8_t[4] * 0.25 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_l * (

                            +delta[a0][b0]*(delta[b1][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[b1][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[b1][d0]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + delta[b1][g0]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[b1][g1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + delta[a0][b1]*(delta[b0][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[b0][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[b0][d0]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + delta[b0][g0]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[b0][g1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + delta[a0][c0]*(delta[b0][b1]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[b0][c1]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + delta[b0][d0]*(delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0]) + delta[b0][g0]*(delta[b1][c1]*delta[d0][g1] + delta[b1][d0]*delta[c1][g1] + delta[b1][g1]*delta[c1][d0]) + delta[b0][g1]*(delta[b1][c1]*delta[d0][g0] + delta[b1][d0]*delta[c1][g0] + delta[b1][g0]*delta[c1][d0])) + delta[a0][c1]*(delta[b0][b1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[b0][c0]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + delta[b0][d0]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + delta[b0][g0]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0]) + delta[b0][g1]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0] + delta[b1][g0]*delta[c0][d0])) + delta[a0][d0]*(delta[b0][b1]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + delta[b0][c0]*(delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0]) + delta[b0][c1]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + delta[b0][g0]*(delta[b1][c0]*delta[c1][g1] + delta[b1][c1]*delta[c0][g1] + delta[b1][g1]*delta[c0][c1]) + delta[b0][g1]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1])) + delta[a0][g0]*(delta[b0][b1]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[b0][c0]*(delta[b1][c1]*delta[d0][g1] + delta[b1][d0]*delta[c1][g1] + delta[b1][g1]*delta[c1][d0]) + delta[b0][c1]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0]) + delta[b0][d0]*(delta[b1][c0]*delta[c1][g1] + delta[b1][c1]*delta[c0][g1] + delta[b1][g1]*delta[c0][c1]) + delta[b0][g1]*(delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1])) + delta[a0][g1]*(delta[b0][b1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]) + delta[b0][c0]*(delta[b1][c1]*delta[d0][g0] + delta[b1][d0]*delta[c1][g0] + delta[b1][g0]*delta[c1][d0]) + delta[b0][c1]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0] + delta[b1][g0]*delta[c0][d0]) + delta[b0][d0]*(delta[b1][c0]*delta[c1][g0] + delta[b1][c1]*delta[c0][g0] + delta[b1][g0]*delta[c0][c1]) + delta[b0][g0]*(delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1]))

                        )

                        + F8_t[4] * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * (

                            +PQ[b0]*PQ[b1]*PQ[c0]*PQ[c1]*delta[a0][g0]*delta[d0][g1]

