                            +((PB_0 - PQ[b0])*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + (PB_1 - PQ[b1])*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]))*(QC_0*(QC_1*delta[d0][d1] + QD_0*delta[c1][d1] + QD_1*delta[c1][d0]) + QC_1*(QD_0*delta[c0][d1] + QD_1*delta[c0][d0]) + QD_0*QD_1*delta[c0][c1])

