                            +(PQ[c0]*QD_0*(PQ[c1]*QD_1 + PQ[d1]*QC_1) + PQ[c1]*QC_0*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_1*(PQ[c0]*QD_1 + PQ[d1]*QC_0))*(PQ[a0]*PQ[g1]*(PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) - PQ[a0]*(PA_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PA_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])) + PQ[b0]*(-PB_1*(PQ[g0]*delta[a0][g1] + PQ[g1]*delta[a0][g0]) + PQ[b1]*(delta[a0][g0]*(-PA_y + PQ[g1]) + delta[a0][g1]*(-PA_x + PQ[g0])) + PQ[g0]*delta[a0][b1]*(-PA_y + PQ[g1]) + (-PA_0 + PQ[a0])*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0])) + PQ[b1]*PQ[g0]*(-PA_0*delta[b0][g1] - PA_y*delta[a0][b0] - PB_0*delta[a0][g1] + PQ[a0]*delta[b0][g1] + PQ[g1]*delta[a0][b0]) - PQ[g1]*(PA_x*PQ[b0]*delta[a0][b1] + PQ[b1]*(PA_0*delta[b0][g0] + PA_x*delta[a0][b0] + PB_0*delta[a0][g0]) + PQ[g0]*(PA_0*delta[b0][b1] + PB_0*delta[a0][b1] + PB_1*delta[a0][b0])))

