                        + F9_t[4] * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_k * (

                            +PQ[a0]*PQ[b0]*PQ[b1]*(PQ[d0]*(QC_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QC_1*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0])) + PQ[d1]*(QC_0*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + QC_1*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])) + QD_0*((PQ[c0] + QC_0)*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + (PQ[c1] + QC_1)*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0])) + QD_1*((PQ[c0] + QC_0)*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + (PQ[c1] + QC_1)*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])))

