                            +2.0*PQ[a0]*PQ[b0]*PQ[b1]*(PQ[d1]*QD_0 + QD_1*(PQ[d0] + QD_0))*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])

