                            +(PQ[a0]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PQ[b0]*(PQ[b1]*delta[a0][g0] + PQ[g0]*delta[a0][b1]) + PQ[b1]*PQ[g0]*delta[a0][b0])*(QC_0*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + QC_1*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + QC_y*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0]) + QD_0*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]))

                            +QC_0*(PQ[a0]*(delta[b0][b1]*(QC_1*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + QC_y*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QD_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QD_1*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0])) + delta[b0][g0]*(QC_1*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1] + delta[b1][g1]*delta[d0][d1]) + QC_y*(delta[b1][c1]*delta[d0][d1] + delta[b1][d0]*delta[c1][d1] + delta[b1][d1]*delta[c1][d0]) + QD_0*(delta[b1][c1]*delta[d1][g1] + delta[b1][d1]*delta[c1][g1] + delta[b1][g1]*delta[c1][d1]) + QD_1*(delta[b1][c1]*delta[d0][g1] + delta[b1][d0]*delta[c1][g1] + delta[b1][g1]*delta[c1][d0])) + delta[b1][g0]*(QC_1*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1] + delta[b0][g1]*delta[d0][d1]) + QC_y*(delta[b0][c1]*delta[d0][d1] + delta[b0][d0]*delta[c1][d1] + delta[b0][d1]*delta[c1][d0]) + QD_0*(delta[b0][c1]*delta[d1][g1] + delta[b0][d1]*delta[c1][g1] + delta[b0][g1]*delta[c1][d1]) + QD_1*(delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1] + delta[b0][g1]*delta[c1][d0]))) + PQ[b0]*(delta[a0][b1]*(QC_1*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + QC_y*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QD_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QD_1*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0])) + delta[a0][g0]*(QC_1*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1] + delta[b1][g1]*delta[d0][d1]) + QC_y*(delta[b1][c1]*delta[d0][d1] + delta[b1][d0]*delta[c1][d1] + delta[b1][d1]*delta[c1][d0]) + QD_0*(delta[b1][c1]*delta[d1][g1] + delta[b1][d1]*delta[c1][g1] + delta[b1][g1]*delta[c1][d1]) + QD_1*(delta[b1][c1]*delta[