                        + F9_t[5] * (-2.0) * S1 * S1 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                            +(PQ[a0]*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PQ[b0]*PQ[b1]*(PA_0*PQ[g0] + PA_x*PQ[a0]))*(PQ[d0]*PQ[d1]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1]) + (PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1])*(PQ[d0]*QD_1 + PQ[d1]*QD_0))

                        )

