                            -PQ[a0]*PQ[b0]*PQ[b1]*PQ[g0]*(QC_0*QD_1*(PQ[g1]*QC_1*QD_0 + QC_y*(PQ[c1]*QD_0 + PQ[d0]*QC_1)) + QC_1*QC_y*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

                        )

