                            +PQ[a0]*PQ[b0]*PQ[b1]*PQ[g0]*(PQ[d1]*QD_0*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1]) + QD_1*(PQ[d0]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1]) + QD_0*(PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1])))

