                            +(PA_0*(PA_x*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1] + PB_y*delta[b0][b1]) + PB_y*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])) + PA_x*PB_y*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*(PA_0*delta[g0][g1] + PA_x*delta[a0][g1] + PB_y*delta[a0][g0]))*(PQ[c0]*QD_0*(PQ[c1]*QD_1 + PQ[d1]*QC_1) + PQ[c1]*QC_0*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_1*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

                        )

                        + F9_t[2] * S1 * inv_S4 * inv_S4 * a_i * (

                            +(PA_0*(PA_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PQ[g0]*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1])) + PA_x*PQ[a0]*(PB_0*delta[b1][g1] + PB_1*delta[b0][g1]))*(QC_0*(PQ[c1]*delta[d0][d1] + PQ[d0]*delta[c1][d1] + PQ[d1]*delta[c1][d0]) + QC_1*(PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0] + delta[d0][d1]*(PQ[c0] + QC_0)) + QD_0*(PQ[d1]*delta[c0][c1] + delta[c0][d1]*(PQ[c1] + QC_1) + delta[c1][d1]*(PQ[c0] + QC_0)) + QD_1*(delta[c0][c1]*(PQ[d0] + QD_0) + delta[c0][d0]*(PQ[c1] + QC_1) + delta[c1][d0]*(PQ[c0] + QC_0)))

                            +(PB_0*delta[b1][g1] + PB_1*delta[b0][g1])*(PA_0*(QC_0*(PQ[c1]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + PQ[d0]*(QC_1*delta[d1][g0] + QD_1*delta[c1][g0]) + PQ[d1]*(QC_1*delta[d0][g0] + QD_0*delta[c1][g0])) + QC_1*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + delta[c0][g0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PA_x*(QC_0*(PQ[c1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + QC_1*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + QD_0*QD_1*(PA_0*(PQ[c0]*delta[c1][g0] + PQ[c1]*delta[c0][g0]) + PA_x*(PQ[c0]*delta[a0][c1] + PQ[c1]*delta[a0][c0])))

                            +PA_0*PA_x*(QC_0*(PQ[c1]*(QD_0*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + PQ[d0]*(QC_1*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + QD_1*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1])) + PQ[d1]*(QC_1*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0]) + QD_0*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]))) + QC_1*(PQ[c0]*(QD_0*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])) + QD_0*QD_1*(PQ[c0]*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]) + PQ[c1]*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])))

                            -(PA_0*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1]))*(PQ[c0]*QD_0*(PQ[c1]*QD_1 + PQ[d1]*QC_1) + PQ[c1]*QC_0*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_1*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

