][g0] - PB_0*PQ[g0]*PQ[g1]*delta[a0][b1] + PB_1*PB_y*PQ[a0]*delta[b0][g0] + PB_1*PB_y*PQ[b0]*delta[a0][g0] + PB_1*PB_y*PQ[g0]*delta[a0][b0] - PB_1*PQ[a0]*PQ[b0]*delta[g0][g1] - PB_1*PQ[a0]*PQ[g0]*delta[b0][g1] - PB_1*PQ[a0]*PQ[g1]*delta[b0][g0] - PB_1*PQ[b0]*PQ[g0]*delta[a0][g1] - PB_1*PQ[b0]*PQ[g1]*delta[a0][g0] - PB_1*PQ[g0]*PQ[g1]*delta[a0][b0] - PB_y*PQ[a0]*PQ[b0]*delta[b1][g0] - PB_y*PQ[a0]*PQ[b1]*delta[b0][g0] - PB_y*PQ[a0]*PQ[g0]*delta[b0][b1] - PB_y*PQ[b0]*PQ[b1]*delta[a0][g0] - PB_y*PQ[b0]*PQ[g0]*delta[a0][b1] - PB_y*PQ[b1]*PQ[g0]*delta[a0][b0])

