            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F9_t[6] * 4.0 * S1 * S1 * S2 * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_j * (

                            +(PQ[a0]*PQ[g1]*(PB_0*PQ[b1]*PQ[g0] + PQ[b0]*(PA_x*PQ[b1] + PB_1*PQ[g0])) + PQ[b0]*PQ[b1]*PQ[g0]*(PA_0*PQ[g1] + PB_y*PQ[a0]))*(PQ[c0]*QD_0*(PQ[c1]*QD_1 + PQ[d1]*QC_1) + PQ[c1]*QC_0*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_1*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

