]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + delta[b0][c1]*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + delta[b0][d0]*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + delta[b0][d1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]) + delta[b0][g0]*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0]))) + delta[b0][b1]*(QC_0*(delta[a0][c1]*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + delta[a0][d0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[a0][d1]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[a0][g0]*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + delta[a0][g1]*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1])) + QC_1*(delta[a0][c0]*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + delta[a0][d0]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[a0][d1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[a0][g0]*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + delta[a0][g1]*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1])) + QC_x*(delta[a0][c0]*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + delta[a0][c1]*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + delta[a0][d0]*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[a0][d1]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[a0][g1]*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])) + QD_0*(delta[a0][c0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[a0][c1]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[a0][d1]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + delta[a0][g0]*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[a0][g1]*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*(delta[a0][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[a0][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[a0][d0]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + delta[a0][g0]*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[a0][g1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + QD_y*(delta[a0][c0]*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + delta[a0][c1]*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + delta[a0][d0]*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + delta[a0][d1]*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]) + delta[a0][g0]*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])))

