                            +PA_0*PB_0*PB_1*(delta[c0][c1]*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + delta[c0][d0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[c0][d1]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[c0][g0]*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + delta[c0][g1]*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]))

