+ PQ[d0]*PQ[g0]*(PB_0*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PB_1*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])))) + PB_0*PB_1*(QC_0*QC_1*(PQ[d0]*(PQ[d1]*(QC_x*delta[a0][g1] + QD_y*delta[a0][g0]) + PQ[g0]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1]) + PQ[g1]*(QC_x*delta[a0][d1] + QD_1*delta[a0][g0])) + PQ[d1]*(PQ[g0]*(QD_0*delta[a0][g1] + QD_y*delta[a0][d0]) + PQ[g1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0])) + PQ[g0]*PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_x*(PQ[c0]*QC_1 + PQ[c1]*QC_0)*(PQ[d0]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1]) + PQ[d1]*(QD_0*delta[a0][g1] + QD_y*delta[a0][d0]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QD_0*(PQ[d1]*QD_y + PQ[g1]*QD_1)*(PQ[c0]*(QC_1*delta[a0][g0] + QC_x*delta[a0][c1]) + PQ[c1]*(QC_0*delta[a0][g0] + QC_x*delta[a0][c0]) + PQ[g0]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0])) + QD_1*QD_y*(PQ[c0]*(PQ[c1]*(QC_x*delta[a0][d0] + QD_0*delta[a0][g0]) + PQ[d0]*(QC_1*delta[a0][g0] + QC_x*delta[a0][c1]) + PQ[g0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a0][g0] + QC_x*delta[a0][c0]) + PQ[g0]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])) + PQ[d0]*PQ[g0]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))) + QC_x*(PA_0*(PB_0*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PB_1*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + PB_0*PB_1*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))*(PQ[d0]*(PQ[d1]*QD_y + PQ[g1]*QD_1) + PQ[d1]*PQ[g1]*QD_0) + QD_0*(PA_0*(PB_0*(QD_1*delta[b1][g1] + QD_y*delta[b1][d1]) + PB_1*(QD_1*delta[b0][g1] + QD_y*delta[b0][d1])) + PB_0*PB_1*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1]))*(PQ[c0]*(PQ[c1]*QC_x + PQ[g0]*QC_1) + PQ[c1]*PQ[g0]*QC_0)

