lta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + QC_x*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0]) + QD_y*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])) + PQ[g0]*(QC_0*(delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]) + QC_1*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0]) + QD_y*(delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0])) + PQ[g1]*(QC_0*(delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1]) + QC_1*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + QC_x*(delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0]))) + PQ[b0]*(PQ[c0]*(QC_1*(delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + QC_x*(delta[a0][c1]*delta[b1][g1] + delta[a0][g1]*delta[b1][c1]) + QD_y*(delta[a0][c1]*delta[b1][g0] + delta[a0][g0]*delta[b1][c1])) + PQ[c1]*(QC_0*(delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + QC_x*(delta[a0][c0]*delta[b1][g1] + delta[a0][g1]*delta[b1][c0]) + QD_y*(delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0])) + PQ[g0]*(QC_0*(delta[a0][c1]*delta[b1][g1] + delta[a0][g1]*delta[b1][c1]) + QC_1*(delta[a0][c0]*delta[b1][g1] + delta[a0][g1]*delta[b1][c0]) + QD_y*(delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0])) + PQ[g1]*(QC_0*(delta[a0][c1]*delta[b1][g0] + delta[a0][g0]*delta[b1][c1]) + QC_1*(delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0]) + QC_x*(delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0]))) + PQ[b1]*(PQ[c0]*(QC_1*(delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + QC_x*(delta[a0][c1]*delta[b0][g1] + delta[a0][g1]*delta[b0][c1]) + QD_y*(delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1])) + PQ[c1]*(QC_0*(delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + QC_x*(delta[a0][c0]*delta[b0][g1] + delta[a0][g1]*delta[b0][c0]) + QD_y*(delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0])) + PQ[g0]*(QC_0*(delta[a0][c1]*delta[b0][g1] + delta[a0][g1]*delta[b0][c1]) + QC_1*(delta[a0][c0]*delta[b0][g1] + delta[a0][g1]*delta[b0][c0]) + QD_y*(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0])) + PQ[g1]*(QC_0*(delta[a0][c1]*delta[b0][g0] + delta[a0][g0]*delta[b0][c1]) + QC_1*(delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0]) + QC_x*(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0])))) - PQ[g0]*PQ[g1]*(PQ[a0]*(PQ[c0]*(QC_1*(delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + QD_0*(delta[b0][c1]*delta[b1][d1] + delta[b0][d1]*delta[b1][c1]) + QD_1*(delta[b0][c1]*delta[b1][d0] + delta[b0][d0]*delta[b1][c1])) + PQ[c1]*(QC_0*(delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + QD_0*(delta[b0][c0]*delta[b1][d1] + delta[b0][d1]*delta[b1][c0]) + QD_1*(delta[b0][c0]*delta[b1][d0] + delta[b0][d0]*delta[b1][c0])) + PQ[d0]*(QC_0*(delta[b0][c1]*delta[b1][d1] + delta[b0][d1]*delta[b1][c1]) + QC_1*(delta[b0][c0]*delta[b1][d1] + delta[b0][d1]*delta[b1][c0]) + QD_1*(delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0])) + PQ[d1]*(QC_0*(delta[b0][c1]*delta[b1][d0] + delta[b0][d0]*delta[b1][c1]) + QC_1*(delta[b0][c0]*delta[b1][d0] + delta[b0][d0]*delta[b1][c0]) + QD_0*(delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0]))) + PQ[b0]*(PQ[c0]*(QC_1*(delta[a0][d0]*delta[b1][d1] + delta[a0][d1]*delta[b1][d0]) + QD_0*(delta[a0][c1]*delta[b1][d1] + delta[a0][d1]*delta[b1][c1]) + QD_1*(delta[a0][c1]*delta[b1][d0] + delta[a0][d0]*delta[b1][c1])) + PQ[c1]*(QC_0*(delta[a0][d0]*delta[b1][d1] + delta[a0][d1]*delta[b1][d0]) + QD_0*(delta[a0][c0]*delta[b1][d1] + delta[a0][d1]*delta[b1][c0]) + QD_1*(delta[a0][c0]*delta[b1][d0] + delta[a0][d0]*delta[b1][c0])) + PQ[d0]*(QC_0*(delta[a0][c1]*delta[b1][d1] + delta[a0][d1]*delta[b1][c1]) + QC_1*(delta[a0][c0]*delta[b1][d1] + delta[a0][d1]*delta[b1][c0]) + QD_1*(delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0])) + PQ[d1]*(QC_0*(delta[a0][c1]*delta[b1][d0] + delta[a0][d0]*delta[b1][c1]) + QC_1*(delta[a0][c0]*delta[b1][d0] + delta[a0][d0]*delta[b1][c0]) + QD_0*(delta[a0][c0]*delta[b1][c1] + delta[a0][c1]*delta[b1][c0]))) + PQ[b1]*(PQ[c0]*(QC_1*(delta[a0][d0]*delta[b0][d1] + delta[a0][d1]*delta[b0][d0]) + QD_0*(delta[a0][c1]*delta[b0][d1] + delta[a0][d1]*delta[b0][c1]) + QD_1*(delta[a0][c1]*delta[b0][d0] + delta[a0][d0]*delta[b0][c1])) + PQ[c1]*(QC_0*(delta[a0][d0]*delta[b0][d1] + delta[a0][d1]*delta[b0][d0]) + QD_0*(delta[a0][c0]*delta[b0][d1] + delta[a0][d1]*delta[b0][c0]) + QD_1*(delta[a0][c0]*delta[b0][d0] + delta[a0][d0]*delta[b0][c0])) + PQ[d0]*(QC_0*(delta[a0][c1]*delta[b0][d1] + delta[a0][d1]*delta[b0][c1]) + QC_1*(delta[a0][c0]*delta[b0][d1] + delta[a0][d1]*delta[b0][c0]) + QD_1*(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0])) + PQ[d1]*(QC_0*(delta[a0][c1]*delta[b0][d0] + delta[a0][d0]*delta[b0][c1]) + QC_1*(delta[a0][c0]*delta[b0][d0] + delta[a0][d0]*delta[b0][c0]) + QD_0*(delta[a0][c0]*delta[b0][c1] + delta[a0][c1]*delta[b0][c0]))))

                            +(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1])*(-PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*QD_y - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_x - PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1]*QD_1 - PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1]*QD_0 - PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_1) + (delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])*(-PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*QD_y - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_x - PQ[c0]*PQ[d0]*PQ[g0]*PQ[g1]*QD_1 - PQ[c0]*PQ[d1]*PQ[g0]*PQ[g1]*QD_0 - PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*QD_y - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QC_x - PQ[c0]*PQ[c1]*PQ[g0]*PQ[g1]*QD_1 - PQ[c0]*PQ[d1]*PQ[g0]*PQ[g1]*QC_1 - PQ[c1]*PQ[d1]*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][d1] + delta[a0][b1]*delta[b0][d1] + delta[a0][d1]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*QD_y - PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QC_x - PQ[c0]*PQ[c1]*PQ[g0]*PQ[g1]*QD_0 - PQ[c0]*PQ[d0]*PQ[g0]*PQ[g1]*QC_1 - PQ[c1]*PQ[d0]*PQ[g0]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*QD_y - PQ[c0]*PQ[c1]*PQ[d0]*PQ[g1]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g1]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g1]*QC_0) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(-PQ[c0]*PQ[c1]*PQ[d0]*PQ[d1]*QC_x - PQ[c0]*PQ[c1]*PQ[d0]*PQ[g0]*QD_1 - PQ[c0]*PQ[c1]*PQ[d1]*PQ[g0]*QD_0 - PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*QC_1 - PQ[c1]*PQ[d0]*PQ[d1]*PQ[g0]*QC_0)

                        )


                    );

            double hess_kl_xy = -eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];

            atomicAdd(
                hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k] * natoms + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + l_prim],
                hess_kl_xy * ik_factor_D * 2.0 * frac_exact_exchange);
