                            +(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1])*(PA_x*PB_0*PQ[b1]*QD_1*QD_y + PA_x*PB_1*PQ[b0]*QD_1*QD_y + PB_0*PB_1*PQ[g0]*QD_1*QD_y) + (delta[a0][c0]*delta[c1][d1] + delta[a0][c1]*delta[c0][d1] + delta[a0][d1]*delta[c0][c1])*(PA_x*PB_0*PQ[b1]*QD_0*QD_y + PA_x*PB_1*PQ[b0]*QD_0*QD_y + PB_0*PB_1*PQ[g0]*QD_0*QD_y) + (delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1] + delta[a0][g1]*delta[c0][c1])*(PA_x*PB_0*PQ[b1]*QD_0*QD_1 + PA_x*PB_1*PQ[b0]*QD_0*QD_1 + PB_0*PB_1*PQ[g0]*QD_0*QD_1) + (delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0])*(PA_x*PB_0*PQ[b1]*QC_1*QD_y + PA_x*PB_1*PQ[b0]*QC_1*QD_y + PB_0*PB_1*PQ[g0]*QC_1*QD_y) + (delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0])*(PA_x*PB_0*PQ[b1]*QC_1*QD_1 + PA_x*PB_1*PQ[b0]*QC_1*QD_1 + PB_0*PB_1*PQ[g0]*QC_1*QD_1) + (delta[a0][c0]*delta[d1][g1] + delta[a0][d1]*delta[c0][g1] + delta[a0][g1]*delta[c0][d1])*(PA_x*PB_0*PQ[b1]*QC_1*QD_0 + PA_x*PB_1*PQ[b0]*QC_1*QD_0 + PB_0*PB_1*PQ[g0]*QC_1*QD_0) + (delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0])*(PA_x*PB_0*PQ[b1]*QC_0*QD_y + PA_x*PB_1*PQ[b0]*QC_0*QD_y + PB_0*PB_1*PQ[g0]*QC_0*QD_y) + (delta[a0][c1]*delta[d0][g1] + delta[a0][d0]*delta[c1][g1] + delta[a0][g1]*delta[c1][d0])*(PA_x*PB_0*PQ[b1]*QC_0*QD_1 + PA_x*PB_1*PQ[b0]*QC_0*QD_1 + PB_0*PB_1*PQ[g0]*QC_0*QD_1) + (delta[a0][c1]*delta[d1][g1] + delta[a0][d1]*delta[c1][g1] + delta[a0][g1]*delta[c1][d1])*(PA_x*PB_0*PQ[b1]*QC_0*QD_0 + PA_x*PB_1*PQ[b0]*QC_0*QD_0 + PB_0*PB_1*PQ[g0]*QC_0*QD_0) + (delta[a0][d0]*delta[d1][g1] + delta[a0][d1]*delta[d0][g1] + delta[a0][g1]*delta[d0][d1])*(PA_x*PB_0*PQ[b1]*QC_0*QC_1 + PA_x*PB_1*PQ[b0]*QC_0*QC_1 + PB_0*PB_1*PQ[g0]*QC_0*QC_1) + (delta[b0][c0]*delta[c1][d0] + delta[b0][c1]*delta[c0][d0] + delta[b0][d0]*delta[c0][c1])*(PA_0*PA_x*PQ[b1]*QD_1*QD_y + PA_0*PB_1*PQ[g0]*QD_1*QD_y + PA_x*PB_1*PQ[a0]*QD_1*QD_y) + (delta[b0][c0]*delta[c1][d1] + delta[b0][c1]*delta[c0][d1] + delta[b0][d1]*delta[c0][c1])*(PA_0*PA_x*PQ[b1]*QD_0*QD_y + PA_0*PB_1*PQ[g0]*QD_0*QD_y + PA_x*PB_1*PQ[a0]*QD_0*QD_y) + (delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1] + delta[b0][g1]*delta[c0][c1])*(PA_0*PA_x*PQ[b1]*QD_0*QD_1 + PA_0*PB_1*PQ[g0]*QD_0*QD_1 + PA_x*PB_1*PQ[a0]*QD_0*QD_1) + (delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])*(PA_0*PA_x*PQ[b1]*QC_1*QD_y + PA_0*PB_1*PQ[g0]*QC_1*QD_y + PA_x*PB_1*PQ[a0]*QC_1*QD_y) + (delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0])*(PA_0*PA_x*PQ[b1]*QC_1*QD_1 + PA_0*PB_1*PQ[g0]*QC_1*QD_1 + PA_x*PB_1*PQ[a0]*QC_1*QD_1) + (delta[b0][c0]*delta[d1][g1] + delta[b0][d1]*delta[c0][g1] + delta[b0][g1]*delta[c0][d1])*(PA_0*PA_x*PQ[b1]*QC_1*QD_0 + PA_0*PB_1*PQ[g0]*QC_1*QD_0 + PA_x*PB_1*PQ[a0]*QC_1*QD_0) + (delta[b0][c1]*delta[d0][d1] + delta[b0][d0]*delta[c1][d1] + delta[b0][d1]*delta[c1][d0])*(PA_0*PA_x*PQ[b1]*QC_0*QD_y + PA_0*PB_1*PQ[g0]*QC_0*QD_y + PA_x*PB_1*PQ[a0]*QC_0*QD_y) + (delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1] + delta[b0][g1]*delta[c1][d0])*(PA_0*PA_x*PQ[b1]*QC_0*QD_1 + PA_0*PB_1*PQ[g0]*QC_0*QD_1 + PA_x*PB_1*PQ[a0]*QC_0*QD_1) + (delta[b0][c1]*delta[d1][g1] + delta[b0][d1]*delta[c1][g1] + delta[b0][g1]*delta[c1][d1])*(PA_0*PA_x*PQ[b1]*QC_0*QD_0 + PA_0*PB_1*PQ[g0]*QC_0*QD_0 + PA_x*PB_1*PQ[a0]*QC_0*QD_0) + (delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1] + delta[b0][g1]*delta[d0][d1])*(PA_0*PA_x*PQ[b1]*QC_0*QC_1 + PA_0*PB_1*PQ[g0]*QC_0*QC_1 + PA_x*PB_1*PQ[a0]*QC_0*QC_1) + (delta[b1][c0]*delta[c1][d0] + delta[b1][c1]*delta[c0][d0] + delta[b1][d0]*delta[c0][c1])*(PA_0*PA_x*PQ[b0]*QD_1*QD_y + PA_0*PB_0*PQ[g0]*QD_1*QD_y + PA_x*PB_0*PQ[a0]*QD_1*QD_y) + (delta[b1][c0]*delta[c1][d1] + delta[b1][c1]*delta[c0][d1] + delta[b1][d1]*delta[c0][c1])*(PA_0*PA_x*PQ[b0]*QD_0*QD_y + PA_0*PB_0*PQ[g0]*QD_0*QD_y + PA_x*PB_0*PQ[a0]*QD_0*QD_y) + (delta[b1][c0]*delta[c1][g1] + de