*delta[a0][c1])) + PB_1*(PQ[a0]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1]) + PQ[b0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1]))) + PB_0*PB_1*(PQ[a0]*(QC_1*delta[d0][g0] + QD_0*delta[c1][g0]) + PQ[g0]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1]))) + (PA_0*(PA_x*(PQ[b0]*delta[b1][c0] + PQ[b1]*delta[b0][c0]) + PB_0*(PQ[b1]*delta[c0][g0] + PQ[g0]*delta[b1][c0]) + PB_1*(PQ[b0]*delta[c0][g0] + PQ[g0]*delta[b0][c0])) + PA_x*(PB_0*(PQ[a0]*delta[b1][c0] + PQ[b1]*delta[a0][c0]) + PB_1*(PQ[a0]*delta[b0][c0] + PQ[b0]*delta[a0][c0])) + PB_0*PB_1*(PQ[a0]*delta[c0][g0] + PQ[g0]*delta[a0][c0]))*(PQ[c1]*QD_1*(PQ[d0]*QD_y + PQ[g1]*QD_0) + PQ[d0]*QC_1*(PQ[d1]*QD_y + PQ[g1]*QD_1) + PQ[d1]*QD_0*(PQ[c1]*QD_y + PQ[g1]*QC_1))

