                        + F9_t[3] * 0.5 * inv_S4 * inv_S4 * inv_S4 * a_j * a_k * (

                            +(PA_0*PQ[b0]*QC_0 + PB_0*PQ[a0]*QC_0)*(delta[b1][c1]*delta[d0][d1]*delta[g0][g1] + delta[b1][c1]*delta[d0][g0]*delta[d1][g1] + delta[b1][c1]*delta[d0][g1]*delta[d1][g0] + delta[b1][d0]*delta[c1][d1]*delta[g0][g1] + delta[b1][d0]*delta[c1][g0]*delta[d1][g1] + delta[b1][d0]*delta[c1][g1]*delta[d1][g0] + delta[b1][d1]*delta[c1][d0]*delta[g0][g1] + delta[b1][d1]*delta[c1][g0]*delta[d0][g1] + delta[b1][d1]*delta[c1][g1]*delta[d0][g0] + delta[b1][g1]*delta[c1][d0]*delta[d1][g0] + delta[b1][g1]*delta[c1][d1]*delta[d0][g0] + delta[b1][g1]*delta[c1][g0]*delta[d0][d1]) + (PA_0*PQ[b0]*QC_1 + PB_0*PQ[a0]*QC_1)*(delta[b1][c0]*delta[d0][d1]*delta[g0][g1] + delta[b1][c0]*delta[d0][g0]*delta[d1][g1] + delta[b1][c0]*delta[d0][g1]*delta[d1][g0] + delta[b1][d0]*delta[c0][d1]*delta[g0][g1] + delta[b1][d0]*delta[c0][g0]*delta[d1][g1] + delta[b1][d0]*delta[c0][g1]*delta[d1][g0] + delta[b1][d1]*delta[c0][d0]*delta[g0][g1] + delta[b1][d1]*delta[c0][g0]*delta[d0][g1] + delta[b1][d1]*delta[c0][g1]*delta[d0][g0] + delta[b1][g1]*delta[c0][d0]*delta[d1][g0] + delta[b1][g1]*delta[c0][d1]*delta[d0][g0] + delta[b1][g1]*delta[c0][g0]*delta[d0][d1]) + (PA_0*PQ[b0]*QC_y + PB_0*PQ[a0]*QC_y)*(delta[b1][c0]*delta[c1][d0]*delta[d1][g0] + delta[b1][c0]*delta[c1][d1]*delta[d0][g0] + delta[b1][c0]*delta[c1][g0]*delta[d0][d1] + delta[b1][c1]*delta[c0][d0]*delta[d1][g0] + delta[b1][c1]*delta[c0][d1]*delta[d0][g0] + delta[b1][c1]*delta[c0][g0]*delta[d0][d1] + delta[b1][d0]*delta[c0][c1]*delta[d1][g0] + delta[b1][d0]*delta[c0][d1]*delta[c1][g0] + delta[b1][d0]*delta[c0][g0]*delta[c1][d1] + delta[b1][d1]*delta[c0][c1]*delta[d0][g0] + delta[b1][d1]*delta[c0][d0]*delta[c1][g0] + delta[b1][d1]*delta[c0][g0]*delta[c1][d0]) + (PA_0*PQ[b0]*QD_0 + PB_0*PQ[a0]*QD_0)*(delta[b1][c0]*delta[c1][d1]*delta[g0][g1] + delta[b1][c0]*delta[c1][g0]*delta[d1][g1] + delta[b1][c0]*delta[c1][g1]*delta[d1][g0] + delta[b1][c1]*delta[c0][d1]*delta[g0][g1] + delta[b1][c1]*delta[c0][g0]*delta[d1][g1] + delta[b1