1) + (delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])*(PA_0*PQ[c0]*QC_1*QC_y*QD_0 + PA_0*PQ[c1]*QC_0*QC_y*QD_0 + PA_0*PQ[d0]*QC_0*QC_1*QC_y + PA_0*PQ[g1]*QC_0*QC_1*QD_0 - PQ[a0]*PQ[c0]*QC_1*QC_y*QD_0 - PQ[a0]*PQ[c1]*QC_0*QC_y*QD_0 - PQ[a0]*PQ[d0]*QC_0*QC_1*QC_y - PQ[a0]*PQ[g1]*QC_0*QC_1*QD_0) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(PA_0*PQ[c0]*QC_1*QD_0*QD_1 + PA_0*PQ[c1]*QC_0*QD_0*QD_1 + PA_0*PQ[d0]*QC_0*QC_1*QD_1 + PA_0*PQ[d1]*QC_0*QC_1*QD_0 - PQ[a0]*PQ[c0]*QC_1*QD_0*QD_1 - PQ[a0]*PQ[c1]*QC_0*QD_0*QD_1 - PQ[a0]*PQ[d0]*QC_0*QC_1*QD_1 - PQ[a0]*PQ[d1]*QC_0*QC_1*QD_0)

