                            +PQ[a0]*((PQ[c0]*delta[c1][g1] + PQ[c1]*delta[c0][g1])*(QD_0*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0])) + (PQ[d0]*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]))*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1])) + (PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[a0][c0]*delta[c1][g1] + delta[a0][c1]*delta[c0][g1])

                            +PQ[a0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[b0][g0]*(delta[b1][c0]*delta[c1][g1] + delta[b1][c1]*delta[c0][g1]) + delta[b1][g0]*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1]))

