                            +(QC_0*QD_1*(PQ[g1]*QC_1*QD_0 + QC_y*(PQ[c1]*QD_0 + PQ[d0]*QC_1)) + QC_1*QC_y*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))*(PA_0*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PQ[a0]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0] + PB_x*delta[b0][b1] - PQ[b0]*delta[b1][g0] - PQ[b1]*delta[b0][g0] - PQ[g0]*delta[b0][b1]) + PQ[b0]*(PB_1*delta[a0][g0] + PB_x*delta[a0][b1]) + PQ[b1]*(PB_x*delta[a0][b0] + delta[a0][g0]*(PB_0 - PQ[b0])) + PQ[g0]*(delta[a0][b0]*(PB_1 - PQ[b1]) + delta[a0][b1]*(PB_0 - PQ[b0])))

