[d1]*(QC_1*delta[d0][g0] + QD_0*delta[c1][g0]))) + PQ[g0]*(PQ[c1]*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + PQ[g1]*(PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])))) + PB_x*(PQ[a0]*(PQ[c1]*(PQ[d0]*(QC_y*delta[b1][d1] + QD_1*delta[b1][g1]) + PQ[d1]*(QC_y*delta[b1][d0] + QD_0*delta[b1][g1]) + PQ[g1]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0])) + PQ[g1]*(PQ[d0]*(QC_1*delta[b1][d1] + QD_1*delta[b1][c1]) + PQ[d1]*(QC_1*delta[b1][d0] + QD_0*delta[b1][c1]))) + PQ[b1]*(PQ[c1]*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + PQ[g1]*(PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1]))))) + PB_1*PB_x*(PQ[a0]*(PQ[c1]*(PQ[d0]*(QC_y*delta[b0][d1] + QD_1*delta[b0][g1]) + PQ[d1]*(QC_y*delta[b0][d0] + QD_0*delta[b0][g1]) + PQ[g1]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + PQ[g1]*(PQ[d0]*(QC_1*delta[b0][d1] + QD_1*delta[b0][c1]) + PQ[d1]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1]))) + PQ[b0]*(PQ[c1]*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + PQ[g1]*(PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1]))))) - PQ[c1]*PQ[g1]*(PA_0*(PB_0*(PQ[b1]*(PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0]))) + PB_1*(PQ[b0]*(PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0]))) + PB_x*(PQ[b0]*(PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0])) + PQ[b1]*(PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])))) + PB_0*(PB_1*(PQ[a0]*(PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0]))) + PB_x*(PQ[a0]*(PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0])) + PQ[b1]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) + PB_1*PB_x*(PQ[a0]*(PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])) + PQ[b0]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) - PQ[d0]*PQ[d1]*(PA_0*(PB_0*(PQ[b1]*(PQ[c0]*(QC_1*delta[g0][g1] + QC_y*delta[c1][g0]) + PQ[c1]*(QC_0*delta[g0][g1] + QC_y*delta[c0][g0]) + PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QC_1*delta[b1][g1] + QC_y*delta[b1][c1]) + PQ[c1]*(QC_0*delta[b1][g1] + QC_y*delta[b1][c0]) + PQ[g1]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]))) + PB_1*(PQ[b0]*(PQ[c0]*(QC_1*delta[g0][g1] + QC_y*delta[c1][g0]) + PQ[c1]*(QC_0*delta[g0][g1] + QC_y*delta[c0][g0]) + PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QC_1*delta[b0][g1] + QC_y*delta[b0][c1]) + PQ[c1]*(QC_0*delta[b0][g1] + QC_y*delta[b0][c0]) + PQ[g1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0]))) + PB_x*(PQ[b0]*(PQ[c0]*(QC_1*delta[b1][g1] + QC_y*delta[b1][c1]) + PQ[c1]*(QC_0*delta[b1][g1] + QC_y*delta[b1][c0]) + PQ[g1]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0])) + PQ[b1]*(PQ[c0]*(QC_1*delta[b0][g1] + QC_y*delta[b0][c1]) + PQ[c1]*(QC_0*delta[b0][g1] + QC_y*delta[b0][c0]) + PQ[g1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])))) + PB_0*(PB_1*(PQ[a0]*(PQ[c0]*(QC_1*delta[g0][g1] + QC_y*delta[c1][g0]) + PQ[c1]*(QC_0*delta[g0][g1] + QC_y*delta[c0][g0]) + PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QC_1*delta[a0][g1] + QC_y*delta[a0][c1]) + PQ[c1]*(QC_0*delta[a0][g1] + QC_y*delta[a0][c0]) + PQ[g1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))) + PB_x*(PQ[a0]*(PQ[c0]*(QC_1*delta[b1][g1] + QC_y*delta[b1][c1]) + PQ[c1]*(QC_0*delta[b1][g1] + QC_y*delta[b1][c0]) + PQ[g1]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0])) + PQ[b1]*(PQ[c0]*(QC_1*delta[a0][g1] + QC_y*delta[a0][c1]) + PQ[c1]*(QC_0*delta[a0][g1] + QC_y*delta[a0][c0]) + PQ[g1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0])))) + PB_1*PB_x*(PQ[a0]*(PQ[c0]*(QC_1*delta[b0][g1] + QC_y*delta[b0][c1]) + PQ[c1]*(QC_0*delta[b0][g1] + QC_y*delta[b0][c0]) + PQ[g1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + PQ[b0]*(PQ[c0]*(QC_1*delta[a0][g1] + QC_y*delta[a0][c1]) + PQ[c1]*(QC_0*delta[a0][g1] + QC_y*delta[a0][c0]) + PQ[g1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))))

